import re
p = "build_out.py"
s = open(p, encoding="utf-8").read()
R = {}
def rep(old_start, new_text):
    # replace the raw string literal that starts with old_start (up to the closing quote)
    global s
    i = s.find('r"' + old_start)
    assert i >= 0, old_start
    j = s.find('", ""', i)
    assert j > i
    s = s[:i] + 'r"' + new_text + s[j:]

rep("本题考查公式类计算。由注释", r"本题考查公式类计算。由注释，投入收益率 = 收益 ÷ 研发支出 − 1，故研发支出 = 收益 ÷（1 + 投入收益率）。用于代工产品的投入收益率 = 390.8% − 96.9% = 293.9%，则其平均研发支出 = $\frac{462.1}{1+293.9\%}=\frac{462.1}{3.939}\approx 117.3$（万元/件）。陷阱：A项217.4是自主品牌产品的研发支出；B项94.2是误用390.8%所得。故正确答案为D。")
rep("本题考查现期比重计算。城镇化率", r"本题考查现期比重计算。城镇化率 = 城镇人口 ÷ 总人口，则2024年末总人口 = $\frac{94350}{67.00\%}\approx 140821$（万人）。女性就业人员3.19亿人即31900万人，占总人口比重 = $\frac{31900}{140821}\approx 22.7\%$。速算：$\frac{3.19}{9.435}\times 67\%\approx 22.6\%$，与A项最接近。陷阱：43.4%是女性占就业人员的比重，并非占总人口的比重。故正确答案为A。")
rep("本题考查增长量计算。2024年全国农民工", r"本题考查增长量计算。2024年全国农民工规模29973万人，较2020年增长4.9%。增长量 = $\frac{29973}{1+4.9\%}\times 4.9\%\approx 1400$（万人）。速算用百化分：$4.9\%\approx\frac{1}{20.4}$，增长量 ≈ $\frac{29973}{21.4}\approx 1400$（万人）。陷阱：直接用 $29973\times 4.9\%\approx 1469$ 是把现期量当作基期量，结果偏大。故正确答案为B。")
rep("本题考查基期比重。2023年三次产业结构", r"本题考查基期比重。2023年三次产业结构为1.05:25.61:73.34，三次产业增速分别为3.5%、2.6%、5.3%，GDP增速4.6%。部分增速低于整体增速，基期比重高于现期；反之则低于。第一、二产业增速低于4.6%，2022年比重应分别高于1.05%、25.61%；第三产业增速高于4.6%，2022年比重应低于73.34%，只有A项满足。验证：2022年三次产业增加值约为307.0、7578.7、21141.7亿元，结构约为1.06:26.11:72.83。故正确答案为A。")
rep("本题考查增长量比较。增长量", r"本题考查增长量比较。增长量 = 现期量 ÷（1 + r）× r，用百化分速算：批发和零售业 ≈ $\frac{4249}{14.5}\approx 293$（$7.4\%\approx\frac{1}{13.5}$）；交通运输、仓储和邮政业 ≈ $\frac{2030}{9.2}\approx 221$；金融业 ≈ $\frac{2737}{14.3}\approx 191$（亿元）；住宿和餐饮业下降10.5%，增长量为负，最小。排序为批发和零售业>交通运输、仓储和邮政业>金融业>住宿和餐饮业。故正确答案为C。")
rep("本题考查增长率的应用", r"本题考查增长趋势预测。2023年规模以上服务业企业营业收入18994.25亿元，增长10.3%。设n年后首次超过2.7万亿元，需 $1.103^n>\frac{27000}{18994.25}\approx 1.42$。$1.103^3\approx 1.342<1.42$，$1.103^4\approx 1.480>1.42$，故n = 4，即2027年首次超过（2026年约2.55万亿元，2027年约2.81万亿元）。速算可借助 $1.1^3=1.331$、$1.1^4=1.4641$。故正确答案为B。")
rep("本题考查两期比重比较。利润率", r"本题考查两期比重比较。利润总额增速30.7%高于营业收入增速10.3%，利润率上升，排除A、B。变化量 = $\frac{A}{B}\times\frac{a-b}{1+a}=\frac{1729.68}{18994.25}\times\frac{30.7\%-10.3\%}{1+30.7\%}\approx 9.1\%\times 0.156\approx 1.4$（个百分点）。验证：2022年利润率约7.7%，2023年约9.1%，上升约1.4个百分点。故正确答案为D。")
rep("本题考查现期比重比较。资产负债率", r"本题考查现期比重比较。资产负债率 = 负债 ÷ 资产，以40%为基准，比较负债 × 2.5与资产：3月50234 < 50392.7；4月50459 < 50472.4；5月50317 < 50496.1；6月51014 > 50906.0。只有6月资产负债率超过40%（约40.08%），其余月份均低于40%，故6月最高。注意4月（约39.99%）与40%非常接近，需精确比较。故正确答案为B。")
rep("本题考查累计值转化与环比增长率", r"本题考查累计值转化与环比增长率。当月值 = 本月累计 − 上月累计。3-6月当月销售费用分别为373.8、312.6、314.3、390.5亿元（如4月 = 1320.8 − 1008.2 = 312.6），最少为4月。4月财务费用 = 16.3 − 15.5 = 0.8（亿元），3月 = 15.5 − 14.0 = 1.5（亿元），环比增长 = $\frac{0.8}{1.5}-1\approx -46.7\%$。陷阱：直接比较累计值会误选3月；4、5月销售费用接近，需精确相减。故正确答案为A。")
rep("本题考查基期比重计算。由表和图", r"本题考查基期比重计算。2024年1-3月业务收入3840亿元，同比增长8.4%（图）；利润总额278.9亿元，同比增长−15.3%。2023年一季度利润率 = $\frac{278.9}{3840}\times\frac{1+8.4\%}{1-15.3\%}\approx 7.26\%\times 1.28\approx 9.3\%$。陷阱：直接用2024年数据得约7.3%，会误选A；基期比重 = 现期比重 ×（1 + 整体增速）÷（1 + 部分增速），不要颠倒。故正确答案为C。")
rep("本题考查间隔基期增长量计算", r"本题考查间隔基期增长量。2024年1-4月业务收入5547亿元，增长3.7%，则2023年1-4月为 $\frac{5547}{1.037}\approx 5349.1$（亿元）；由图，2023年1-4月增长3.3%，增长量 = $\frac{5349.1}{1.033}\times 3.3\%\approx 170.9$（亿元）。速算：$3.3\%\approx\frac{1}{30.3}$，增长量 ≈ $\frac{5349}{31.3}\approx 171$。注意3.7%只用于还原2023年数值，求增长量要用2023年增速3.3%。故正确答案为A。")
rep("本题考查现期比重计算。2024年上半年全国", r"本题考查现期比重计算。2024年上半年全国互联网业务收入8676亿元（表中1-6月），中部、西部、东北分别为408.8、525.4、20.8亿元，则东部 = 8676 − 408.8 − 525.4 − 20.8 = 7721（亿元），比重 = $\frac{7721}{8676}\approx 89.0\%$。速算：其余三地区合计955亿元，约占11%，东部约占89%。东部增速信息为干扰项，求现期比重无需使用。故正确答案为B。")
rep("本题考查综合分析，选错误的。A项：利润率", r"本题考查综合分析，选错误的。A项：利润率同比下降等价于利润增速低于收入增速。1-2月至1-6月利润增速（6.5%、−15.3%、−19.7%、−12.8%、1.9%）均低于对应收入增速（7.6%、8.4%、3.7%、5.0%、5.6%），正确。B项：二季度利润 = 743.7 − 278.9 = 464.8（亿元），$\frac{464.8}{278.9}\approx 1.67$，约为1.7:1，正确。C项：2023年1-2月、1-3月、1-4月收入分别约为2289、3542、5349亿元，3月约1253亿元，4月约1807亿元，4月高于3月，正确。D项：东部增速5.2%，中部12.0%，西部4.6%，东北−2.1%，变化幅度最大的是中部，错误。故正确答案为D。")
rep("本题考查基期量计算（环比）", r"本题考查基期量计算（环比）。2023年6月进出口总值3.49万亿元，环比增长1.2%，且环比增速与5月持平，即5月环比也增长1.2%。则5月 = $\frac{3.49}{1.012}\approx 3.45$（万亿元），4月 = $\frac{3.45}{1.012}\approx 3.41$（万亿元）。用二季度总值验证：4月 ≈ 10.34 − 3.49 − 3.45 = 3.40（万亿元），均约为3.4万亿元。注意需连续还原两次环比。故正确答案为B。")
rep("本题考查一般增长率计算（结合比重）", r"本题考查一般增长率计算。民营企业进出口10.59万亿元，占比52.7%，同比提升3.3个百分点，则2022年上半年占比49.4%。2022年上半年进出口总值 = $\frac{11.46}{1.037}+\frac{8.64}{0.999}\approx 19.70$（万亿元），民营企业约 $19.70\times 49.4\%\approx 9.73$（万亿元），增长率 = $\frac{10.59}{9.73}-1\approx 8.8\%$，约为9%。陷阱：不能把3.3个百分点当作增长率。故正确答案为A。")
rep("本题考查间隔基期的平均数增长率", r"本题考查平均数增长率（间隔）。2022年重量增速为1.5% − 4.1% = −2.6%；金额降幅1.2%比上年收窄2.8个百分点，则2022年金额下降4.0%。2023年较2021年，重量增长 $1.015\times 0.974-1\approx -1.14\%$，金额增长 $0.988\times 0.96-1\approx -5.15\%$，平均每吨金额增长率 = $\frac{-5.15\%+1.14\%}{1-1.14\%}\approx -4.1\%$。陷阱：“降幅收窄”说明上年降幅更大。故正确答案为C。")
rep("本题考查增长率计算。2022年较2021年", r"本题考查增长率计算。2022年较2021年：①回收数量减少1400万台，$\frac{1400}{20200}\approx 6.9\%$，降幅未超过10%；②回收重量减少48万吨，$\frac{48}{463}\approx 10.4\%$，降幅超过10%；③回收金额由222.4亿元增至227.4亿元，为增长。速算：降幅超过10%即减少量超过上年值的十分之一，1400 < 2020，48 > 46.3。只有②符合，共1项。故正确答案为B。")
rep("本题考查平均数计算。平均每吨回收金额", r"本题考查平均数计算。平均每吨回收金额 = 回收金额 ÷ 回收重量，亿元 ÷ 万吨 = 万元/吨，超过5000元即金额（亿元）> 重量（万吨）× 0.5。2020年：155.5 < 213；2021年：222.4 < 231.5；2022年：227.4 > 207.5；2023年：231.0 > 210。只有2022年（约5480元/吨）和2023年（5500元/吨）超过5000元，共2个。故正确答案为C。")
